def add_boundary_to_city(city_name_ar: str, boundary_wkt: str, city_name_he: str = None):
    """מוסיף boundary לעיר לפי שם בערבית (או עברית אם לא נמצא)"""
    db = SessionLocal()
    try:
        # חיפוש העיר - קודם לפי ערבית, אם לא נמצא אז לפי עברית
        city = db.execute(
            text("SELECT id, name_ar, name_he FROM cities WHERE name_ar = :name_ar"),
            {"name_ar": city_name_ar}
        ).fetchone()
        
        # אם לא נמצא לפי ערבית, נסה לפי עברית
        if not city and city_name_he:
            city = db.execute(
                text("SELECT id, name_ar, name_he FROM cities WHERE name_he = :name_he"),
                {"name_he": city_name_he}
            ).fetchone()
        
        if not city:
            print(f"❌ עיר '{city_name_ar}' (או '{city_name_he}') לא נמצאה במסד הנתונים")
            print(f"   נסה להריץ את הפונקציה list_all_cities() כדי לראות את כל הערים")
            return False
        
        city_id = city[0]
        
        # הוספת boundary
        # שימוש ב-ST_GeomFromText ליצירת geometry מ-WKT
        db.execute(
            text("""
                UPDATE cities 
                SET boundary = ST_GeomFromText(:boundary_wkt, 4326)::geography
                WHERE id = :city_id
            """),
            {
                "boundary_wkt": boundary_wkt.strip(),
                "city_id": city_id
            }
        )
        
        db.commit()
        print(f"✅ הוסף boundary לעיר '{city_name_ar}' (ID: {city_id})")
        return True
        
    except Exception as e:
        db.rollback()
        print(f"❌ שגיאה בהוספת boundary לעיר '{city_name_ar}': {e}")
        return False
    finally:
        db.close()


def list_all_cities():
    """מציג את כל הערים במסד הנתונים כדי לבדוק את השמות"""
    db = SessionLocal()
    try:
        cities = db.execute(
            text("SELECT id, name_ar, name_he, name_en FROM cities ORDER BY id")
        ).fetchall()
        
        if cities:
            print("\n📋 כל הערים במסד הנתונים:")
            print("-" * 60)
            for city in cities:
                print(f"ID: {city[0]} | ערבית: {city[1]} | עברית: {city[2]} | אנגלית: {city[3]}")
            print("-" * 60)
        else:
            print("❌ לא נמצאו ערים במסד הנתונים")
    except Exception as e:
        print(f"❌ שגיאה בטעינת ערים: {e}")
    finally:
        db.close()


def main():
    # הצגת כל הערים קודם
    list_all_cities()
    
    print("\n🚀 מתחיל הוספת boundaries ל-3 הערים...")
    print("=" * 50)
    
    # הוספת boundaries
    # חשוב: השמות כאן הם name_ar (בערבית) כפי שהם במסד הנתונים
    add_boundary_to_city("رهط", RAHAT_BOUNDARY, "רהט")  # רהט
    add_boundary_to_city("لقية", LAQIYA_BOUNDARY, "לקיה")  # לקיה
    add_boundary_to_city("تل السبع", TEL_SHEVA_BOUNDARY, "תל שבע")  # תל שבע
    
    print("=" * 50)
    print("✅ סיום הוספת boundaries")
    print("\n" + "=" * 50)
    print("⚠️  חשוב מאוד:")
    print("   הנתונים כאן הם דוגמה בלבד ולא נכונים!")
    print("   צריך לעדכן את ה-boundaries עם הערכים האמיתיים של כל עיר.")
    print("\n   אפשרויות להורדת boundaries אמיתיים:")
    print("   1. OpenStreetMap - חפש את העיר וצור export של ה-boundary")
    print("   2. כלי GIS כמו QGIS")
    print("   3. Overpass API של OpenStreetMap")
    print("   4. Google Maps API (אם יש לך מפתח)")
    print("\n   פורמט: POLYGON((lon1 lat1, lon2 lat2, ..., lon1 lat1))")
    print("   חשוב: הנקודה האחרונה חייבת להיות זהה לראשונה!")
    print("=" * 50)


